"use client";
import {ArtemisScope} from "./artemis-scope";
import type { ArtemisPricingContent } from "./components/pricing/content";
import View0 from "./components/pricing/variants/01-ai";
import View1 from "./components/pricing/variants/02-shared-benefits";
import View2 from "./components/pricing/variants/05-aurora-flow";
import View3 from "./components/pricing/variants/06-visual-plans";
import View4 from "./components/pricing/variants/07-command-deck";
import View5 from "./components/pricing/variants/08-ledger";
import View6 from "./components/pricing/variants/11-plans-grid";
const views={"ai":View0,"shared-benefits":View1,"aurora-flow":View2,"visual-plans":View3,"command-deck":View4,"ledger":View5,"plans-grid":View6};
export type { ArtemisPricingBenefits, ArtemisPricingBilling, ArtemisPricingCalculator, ArtemisPricingContent, ArtemisPricingImage, ArtemisPricingLink, ArtemisPricingPlan, ArtemisPricingTier } from "./components/pricing/content";
export interface ArtemisPricingProps {className?:string;variant?:"ai"|"shared-benefits"|"aurora-flow"|"visual-plans"|"command-deck"|"ledger"|"plans-grid";/** The words on the pricing section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisPricingContent>;}
export function ArtemisPricing({className,variant="ai",content}:ArtemisPricingProps){const View=views[variant];return <ArtemisScope className={`art:[&>*]:mx-auto ${className??""}`}><View content={content}/></ArtemisScope>;}

// @zeus-internal

/** The words on a button or link, and where it goes. */
export interface ArtemisPricingLink {
  label: string;
  href: string;
}

/** A picture shown as content. */
export interface ArtemisPricingImage {
  src: string;
  alt: string;
}

/** The two options of the billing switch. */
export interface ArtemisPricingBilling {
  /** The monthly option. */
  monthly: string;
  /** The yearly option. */
  yearly: string;
  /** What paying yearly saves, such as "Save 20%". command-deck and ledger add it to the yearly option, plans-grid shows it beside it. ledger's estimate takes 20% off whatever this says. */
  saving?: string;
}

/** A usage level of a plan, with its own price. */
export interface ArtemisPricingTier {
  /** The tier's option in the plan's switch, such as "5x". */
  label: string;
  /** Replaces the plan's `price` while the tier is chosen. */
  price?: number;
  /** Replaces the plan's `yearlyPrice` while the tier is chosen. */
  yearlyPrice?: number;
  /** Replaces the plan's `description` while the tier is chosen. */
  description?: string;
  /** Replaces the plan's `cta` while the tier is chosen. */
  cta?: ArtemisPricingLink;
}

/** A plan and its price. */
export interface ArtemisPricingPlan {
  /** A short id such as "pro". shared-benefits uses it as the plan picker's value, or the name when left out. */
  id?: string;
  /** All layouts. */
  name: string;
  /** Who the plan is for. All layouts but aurora-flow. */
  description?: string;
  /** The price per month, or the one-off price, as a number of `currency`. All layouts; ledger adds seats to it. */
  price?: number;
  /** The price per month when billed yearly. ai, shared-benefits, command-deck and plans-grid show it while yearly is chosen, and keep `price` without it. */
  yearlyPrice?: number;
  /** Words shown instead of the price, such as "Free" or "Custom pricing". All layouts. */
  priceLabel?: string;
  /** An earlier price, struck through beside the price. plans-grid. */
  compareAtPrice?: number;
  /** After the price, such as "/ month" or "one time". All layouts. */
  period?: string;
  /** A short line about the price, such as "Billed monthly": under the price in ai, shared-benefits and command-deck, at the foot of the card in plans-grid. With `yearlyNote`, it shows only while monthly is chosen. */
  note?: string;
  /** The line in place of `note` while yearly is chosen, such as "{total} billed yearly"; "{total}" becomes the yearly total with its currency. ai, shared-benefits, command-deck and plans-grid. */
  yearlyNote?: string;
  /** A small tag beside the name, such as "Best value". aurora-flow, visual-plans and plans-grid. */
  badge?: string;
  /** Marks the plan to recommend. ai, visual-plans, command-deck and plans-grid draw it apart; shared-benefits and ledger open on it; aurora-flow shows it. */
  featured?: boolean;
  /** A small heading over the features. ai and visual-plans. */
  featuresTitle?: string;
  /** What the plan includes. All layouts; shared-benefits lists them on one line. */
  features: string[];
  /** The plan's button. All layouts; shared-benefits and ledger show the chosen plan's. "{billing}" in the href becomes the chosen period, "monthly" or "annual" ("yearly" in shared-benefits; always "monthly" in layouts without a switch). */
  cta: ArtemisPricingLink;
  /** Usage levels with their own price, shown as a switch on the plan. ai. */
  tiers?: ArtemisPricingTier[];
  /** Seats the price includes. ledger. */
  includedSeats?: number;
  /** The monthly price of each seat after `includedSeats`. ledger. */
  seatPrice?: number;
}

/** What every plan includes. */
export interface ArtemisPricingBenefits {
  /** A small line over the title. */
  badge?: string;
  title: string;
  items: string[];
}

/** The words on ledger's seat calculator and estimate. The maths stays in the layout. */
export interface ArtemisPricingCalculator {
  /** Before each plan's price in the plan picker, such as "From". */
  from: string;
  /** Before the chosen plan's name, over its details, such as "Selected". */
  selected: string;
  /** After the chosen plan's price, such as "/ base". */
  base: string;
  /** Over the seat count, such as "Team size". */
  teamSize: string;
  /** After the seat count, such as "seats". */
  seats: string;
  /** After the seats a plan includes, such as "included". */
  included: string;
  /** After the price of each extra seat, such as "thereafter". */
  thereafter: string;
  /** Before the chosen plan's name, over the estimate, such as "Estimate". */
  estimate: string;
  /** A tag under the estimate's title, such as "Updates live". */
  live: string;
  /** The estimate's line for the plan's price, such as "Base plan". */
  basePlan: string;
  /** After the number of included seats, such as "included seats". */
  includedSeats: string;
  /** After the number of extra seats, such as "additional seats". */
  extraSeats: string;
  /** The estimate's line for the yearly discount, such as "Annual discount". */
  discount: string;
  /** Over the total, such as "Due monthly". */
  total: string;
  /** After the total, such as "USD". */
  currencyCode: string;
}

/** The words on an Artemis pricing section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisPricingContent {
  /** A short line over the headline. ai, aurora-flow, visual-plans, command-deck, ledger and plans-grid. */
  badge?: string;
  /** All layouts. */
  headline: string;
  /** A sentence or two under the headline. All layouts but ledger. */
  subhead?: string;
  /** The sign before every price, such as "$". All layouts. */
  currency: string;
  /** The billing switch. ai, shared-benefits, command-deck, ledger and plans-grid. */
  billing?: ArtemisPricingBilling;
  /** All layouts. aurora-flow shows the featured plan, or the first; visual-plans looks best with two, the others with three. */
  plans: ArtemisPricingPlan[];
  /** A heading over the plan picker. shared-benefits. */
  plansTitle?: string;
  /** What every plan includes, beside the plan picker. shared-benefits. */
  benefits?: ArtemisPricingBenefits;
  /** The picture over the benefits. shared-benefits. */
  image?: ArtemisPricingImage;
  /** A line of small print: under the plans in ai and plans-grid, under the subhead in aurora-flow, under the button in ledger. */
  footnote?: string;
  /** The words on the seat calculator. ledger. */
  calculator?: ArtemisPricingCalculator;
}

"use client";
// @zeus-internal
import { useState, type CSSProperties } from "react";
import { motion } from "motion/react";
import { useArtemisDark } from "../../../lib/use-dark";
import { darkBeam, lightBeam } from "./01-ai/beam";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { PricingTabs, PriceNumber } from "./01-ai/controls";
import type { ArtemisPricingContent, ArtemisPricingPlan } from "../content";
const DEFAULT = {
    badge: "Simple plans. More room to think.",
    headline: "A little help. A bigger possibility.",
    subhead: "From your first question to your most ambitious work. Find the space to think, create, and go further.",
    currency: "$",
    billing: { monthly: "Monthly", yearly: "Yearly" },
    plans: [
        {
            name: "Free",
            price: 0,
            period: "/ forever",
            note: "No credit card needed",
            description: "Start with the essentials. Upgrade when you need more space.",
            cta: { label: "Start for free", href: "/signup?plan=free&billing={billing}&usage=5x" },
            featuresTitle: "A useful place to start",
            features: ["Everyday questions and writing", "Standard model access", "Limited file and image uploads", "Saved conversations"],
        },
        {
            name: "Pro",
            price: 40,
            yearlyPrice: 32,
            period: "/ month",
            note: "Billed monthly",
            yearlyNote: "{total} billed yearly",
            description: "5\u00D7 usage for everyday work. More room to write, research, and create.",
            cta: { label: "Get Pro 5\u00D7", href: "/signup?plan=pro&billing={billing}&usage=5x" },
            featured: true,
            featuresTitle: "Everything in Free, plus",
            features: ["Our most capable models", "Deep research and advanced reasoning", "Larger files and longer conversations", "Projects with persistent context", "Priority access during busy hours"],
            tiers: [
                { label: "5x" },
                { label: "20x", price: 100, yearlyPrice: 80, description: "20\u00D7 usage for your biggest ideas. Go deeper with longer, more demanding work.", cta: { label: "Get Pro 20\u00D7", href: "/signup?plan=pro&billing={billing}&usage=20x" } },
            ],
        },
        {
            name: "Team",
            price: 30,
            yearlyPrice: 24,
            period: "/ person / month",
            note: "Billed monthly",
            yearlyNote: "{total} billed yearly per person",
            description: "5\u00D7 usage for every person. Start with 2 or more teammates.",
            cta: { label: "Create a team", href: "/signup?plan=team&billing={billing}&usage=5x" },
            featuresTitle: "Built for shared work",
            features: ["Everything in Pro at 5\u00D7 usage per seat", "A shared workspace for your team", "Centralized billing and admin controls", "Team content excluded from training", "Manage members and permissions"],
        },
    ],
    footnote: "Usage limits apply. Allowances vary with model, message length, and tools. Taxes may apply.",
} satisfies ArtemisPricingContent;
export default function PricingAi({ content }: { content?: Partial<ArtemisPricingContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const plans: ArtemisPricingPlan[] = copy.plans;
    const dark = useArtemisDark();
    const [billing, setBilling] = useState("monthly");
    const [usage, setUsage] = useState<Record<number, number>>({});
    const [sweep, setSweep] = useState({ plan: 0, count: 0 });
    function changeUsage(plan: number, value: string) {
        const tier = Number(value);
        if (tier === (usage[plan] ?? 0))
            return;
        setUsage(current => ({ ...current, [plan]: tier }));
        setSweep(current => ({ plan, count: current.count + 1 }));
    }
    const annual = billing === "annual";
    return (<>
      <section className="art:w-full art:bg-background art:text-foreground">
        <div className="art:mx-auto art:max-w-7xl art:px-6 art:pb-16 art:@min-[640px]/artemis:px-10">
          <div className="art:mx-auto art:max-w-2xl art:pb-9 art:pt-10 art:text-center art:@min-[640px]/artemis:pt-16">
            {copy.badge && <p className="art:mb-4 art:text-xs art:font-medium art:text-muted-foreground">
              {copy.badge}
            </p>}
            <h2 className="art:text-balance art:text-4xl art:font-medium art:tracking-tight">
              {copy.headline}
            </h2>
            {copy.subhead && <p className="art:mx-auto art:mt-5 art:max-w-lg art:text-pretty art:text-sm art:leading-6 art:text-muted-foreground art:@min-[640px]/artemis:text-base">
              {copy.subhead}
            </p>}
            {copy.billing && <div className="art:mt-7">
              <PricingTabs label="Billing period" className="art:inline-flex art:items-center art:gap-1 art:rounded-full art:bg-muted art:p-1" buttonClassName="art:relative art:z-10 art:inline-flex art:items-center art:justify-center art:whitespace-nowrap art:bg-transparent art:py-1.5 art:font-medium art:text-sm art:outline-none art:transition-colors art:duration-150 art:motion-reduce:delay-0 art:motion-reduce:transition-none art:rounded-full art:h-9 art:px-4 art:focus-visible:outline-2 art:focus-visible:outline-offset-2 art:focus-visible:outline-ring" value={billing} onChange={setBilling} options={[{ value: "monthly", label: copy.billing.monthly }, { value: "annual", label: copy.billing.yearly }]}/>
            </div>}
          </div>
          <div className="art:grid art:gap-4 art:@min-[1024px]/artemis:grid-cols-3">
            {plans.map((plan, index) => {
                const tier = usage[index] ?? 0;
                const shown = { ...plan, ...plan.tiers?.[tier] };
                const price = (annual ? shown.yearlyPrice : undefined) ?? shown.price ?? 0;
                const note = annual && shown.yearlyNote !== undefined ? shown.yearlyNote.replace("{total}", `${copy.currency}${Math.round(price * 1200) / 100}`) : shown.note;
                return <motion.section key={index} className="art:relative art:isolate art:flex art:flex-col art:rounded-3xl art:border art:bg-background art:p-6 art:@min-[640px]/artemis:p-7 art:border-border" initial={{ opacity: 0, y: 14 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, amount: 0.2 }} transition={{ duration: 0.45, ease: ARTEMIS_EASE_OUT, delay: index * 0.06 }}>
              {plan.featured && <>
              <style>{dark ? darkBeam : lightBeam}</style>
              <div aria-hidden="true" data-beam="_R_3apbsnpfdb_" data-active="" className="art:pointer-events-none art:rounded-3xl art:[&>[data-beam-bloom]]:hidden" style={{ position: "absolute", inset: "-1px", "--beam-strength": tier === 0 ? "0.55" : "1" } as CSSProperties}>
                <div className="art:size-full art:rounded-3xl"/>
                <div data-beam-bloom="true"/>
              </div>
              </>}
              {sweep.count > 0 && sweep.plan === index && <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0 art:-z-10 art:overflow-hidden art:rounded-3xl">
                <motion.div key={sweep.count} className="art:absolute art:inset-0" style={{ background: "radial-gradient(rgba(251, 191, 136, 0.3), rgba(252, 220, 179, 0.14) 38%, transparent 70%)" }} initial={{ opacity: 0, x: "-65%", y: "40%" }} animate={{ opacity: [0, 1, 0], x: "65%", y: "-40%" }} transition={{ duration: 1.2, ease: ARTEMIS_EASE_OUT }}/>
              </div>}
              <div className="art:flex art:min-h-11 art:items-center art:justify-between art:gap-4">
                <h2 className="art:text-xl art:font-medium">
                  {plan.name}
                </h2>
                {plan.tiers && <div>
                  <PricingTabs label={`${plan.name} usage`} className="art:inline-flex art:items-center art:rounded-full art:bg-muted art:gap-0.5 art:p-1" buttonClassName="art:relative art:z-10 art:inline-flex art:items-center art:justify-center art:whitespace-nowrap art:bg-transparent art:font-medium art:outline-none art:transition-colors art:duration-150 art:motion-reduce:delay-0 art:motion-reduce:transition-none art:rounded-full art:h-7 art:min-w-12 art:px-3 art:py-1 art:text-xs art:before:absolute art:before:-inset-y-1.5 art:before:inset-x-0 art:before:content-[''] art:focus-visible:outline-2 art:focus-visible:outline-offset-2 art:focus-visible:outline-ring" value={String(tier)} onChange={value => changeUsage(index, value)} options={plan.tiers.map((option, value) => ({ value: String(value), label: option.label }))}/>
                </div>}
              </div>
              <div className="art:mt-6">
                <span className="art:inline-flex art:items-end art:font-sans art:text-foreground art:tabular-nums art:text-5xl art:font-medium art:tracking-tight">
                  {plan.priceLabel ?? <>
                  <span className="art:self-start art:pt-[0.12em] art:text-base art:text-muted-foreground">
                    {copy.currency}
                  </span>
                  <PriceNumber value={price}/>
                  </>}
                </span>
                {plan.priceLabel === undefined && plan.period && <span className="art:ml-1 art:text-xs art:text-muted-foreground">
                  {plan.period}
                </span>}
              </div>
              <p className="art:mt-1 art:min-h-5 art:text-xs art:text-muted-foreground">
                {note}
              </p>
              <div className="art:my-6 art:min-h-20">
                <p className="art:pt-3 art:text-sm art:leading-6 art:text-muted-foreground">
                  {shown.description}
                </p>
              </div>
              <motion.a whileHover={{ scale: 1.01 }} whileTap={{ scale: 0.98 }} transition={{ duration: 0.2, ease: ARTEMIS_EASE_OUT }} className={plan.featured ? "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-10 art:w-full art:rounded-full" : "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-10 art:w-full art:hover:bg-muted art:rounded-full"} href={shown.cta.href.split("{billing}").join(billing)} tabIndex={0}>
                {shown.cta.label}
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-right art:size-4" aria-hidden="true">
                  <path d="M5 12h14"/>
                  <path d="m12 5 7 7-7 7"/>
                </svg>
              </motion.a>
              <p className="art:mb-4 art:mt-7 art:text-xs art:font-medium">
                {plan.featuresTitle}
              </p>
              <ul className="art:space-y-3">
                {plan.features.map((feature, item) => <li key={item} className="art:flex art:gap-2.5 art:text-sm art:leading-5 art:text-muted-foreground">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check art:mt-0.5 art:size-4 art:shrink-0 art:text-foreground" aria-hidden="true">
                    <path d="M20 6 9 17l-5-5"/>
                  </svg>
                  {feature}
                </li>)}
              </ul>
            </motion.section>;
            })}
          </div>
          {copy.footnote && <p className="art:mt-5 art:text-center art:text-xs art:leading-5 art:text-muted-foreground">
            {copy.footnote}
          </p>}
        </div>
      </section>
    </>);
}

